const raw = $input.first().json.body ?? $input.first().json;
const required = ['customer_email', 'service', 'scope', 'quoted_amount', 'currency'];
const missing = required.filter((key) => !String(raw[key] ?? '').trim());
const email = String(raw.customer_email ?? '').trim();
const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const amount = Number(raw.quoted_amount);
const errors = missing.map((key) => `Missing ${key}`);
if (email && !validEmail) errors.push('Invalid customer email');
if (!Number.isFinite(amount) || amount <= 0) errors.push('quoted_amount must be a positive number');
const order = {
  order_id: `AXO-${Date.now()}`,
  customer_email: email,
  customer_name: String(raw.customer_name ?? '').trim(),
  service: String(raw.service ?? '').trim(),
  scope: String(raw.scope ?? '').trim(),
  quoted_amount: Number.isFinite(amount) ? amount : null,
  currency: String(raw.currency ?? '').trim().toUpperCase(),
  received_at: new Date().toISOString(),
  status: 'AWAITING_HUMAN_REVIEW',
  payment_status: 'NOT_VERIFIED',
  file_status: 'NOT_RECEIVED',
  delivery_status: 'NOT_AUTHORIZED',
  approval_required: true
};
return [{ json: { ok: errors.length === 0, errors, order, safety_note: 'This workflow does not confirm payment, send an email, process a client workbook, or deliver files. Verify scope and payment manually before progressing.' } }];
